      controller.setPaneDrag(null)
      if (dropped) void controller.movePane(paneId, dropped)
    }
    window.addEventListener('mousemove', onMove)
    window.addEventListener('mouseup', onUp)
  }

async movePane(paneId: string, to: PaneDropTarget): Promise<void> {
    const params = to.kind === 'edge' ? { pane: paneId, toPane: to.pane, edge: to.edge } : { pane: paneId, toTab: to.tab }
    await this.run(() => this.context.call('quirky.terminal/movePane', params), 'move the pane')
  }

const startDivider = (divider: DividerRect, event: ReactMouseEvent) => {
    if (event.button !== 0) return
    event.preventDefault()
    const element = container.current
    if (!element) return
    const total = divider.direction === 'right' ? divider.area.width : divider.area.height
    const minPane = divider.direction === 'right' ? MIN_PANE_PX : minPaneHeight
    const lowest = Math.min(minPane, total / 2) / total
    const original = splitRatioOf(tab.root, divider.split)
    let latest: { kind: 'pane'; split: string; ratio: number } | null = null
    const onMove = (move: MouseEvent) => {
      const rect = element.getBoundingClientRect()
      const offset = divider.direction === 'right' ? move.clientX - rect.left - divider.area.x : move.clientY - rect.top - divider.area.y
      const ratio = Math.min(1 - lowest, Math.max(lowest, offset / total))
      latest = { kind: 'pane', split: divider.split, ratio: roundRatio(ratio) }
      controller.previewDivider(latest)
    }
    const onUp = () => {
      window.removeEventListener('mousemove', onMove)
      window.removeEventListener('mouseup', onUp)
      void controller.endDividerDrag(latest, latest !== null && latest.ratio !== original)
    }
    window.addEventListener('mousemove', onMove)
    window.addEventListener('mouseup', onUp)
  }

async endDividerDrag(preview: Preview | null, changed: boolean): Promise<void> {
    this.set({ dragging: false })
    if (!preview || !changed) {
      this.set({ preview: null })
      return
    }
    const ws = this.ws
    const result = await this.run(() => this.context.call('quirky.terminal/resizeSplit', { split: preview.split, ratio: preview.ratio, ...(ws ? { revision: ws.revision } : {}) }), 'resize the split')
    if (!result) this.set({ preview: null })
  }

async resetDivider(split: string): Promise<void> {
    const ws = this.ws
    await this.run(() => this.context.call('quirky.terminal/resizeSplit', { split, ratio: 0.5, ...(ws ? { revision: ws.revision } : {}) }), 'resize the split')
  }

const submit = (event: FormEvent) => {
    event.preventDefault()
    if (canSubmit) onSubmit(prompt)
  }

export async function runWorkspaceViewAction(context: UiPluginContext, args: WorkspaceViewActionArgs): Promise<void> {
  let result: unknown
  try {
    result = await requestWindowCommand(context, { command: 'command:quirky.terminal/workspace-view-action', args })
  } catch (error) {
    context.toast('Could not run workspace action', messageOf(error))
    return
  }
  if (result && typeof result === 'object' && 'ok' in result && result.ok === false) {
    const reason = 'reason' in result && typeof result.reason === 'string' ? result.reason : 'The command was refused.'
    context.toast('Could not run workspace action', reason)
  }
}
